  assign MinimumTree_treestage4_isless = MinimumTree_stage3_val_reg[0] <= MinimumTree_stage3_val_reg[1];
  assign MinimumTree_stage4_val = (MinimumTree_treestage4_isless ? MinimumTree_stage3_val_reg[0] :
              MinimumTree_stage3_val_reg[1]);
  assign MinimumTree_stage4_idx = (MinimumTree_treestage4_isless ? MinimumTree_stage3_idx_reg[0] :
              MinimumTree_stage3_idx_reg[1]);

  always @(posedge clk or posedge reset)
    begin : MinimumTree_stage4_val_1_process
      if (reset == 1'b1) begin
        MinimumTree_stage4_val_reg <= 5'b00000;
      end
      else begin
        if (enb_1_2_0) begin
          MinimumTree_stage4_val_reg <= MinimumTree_stage4_val;
        end
      end
    end

  assign sel = MinimumTree_stage4_val_reg < 5'b01000;

  assign switch_compare_1 = sel > 1'b0;

  // Normalization constant adjustment value
  assign conststep = 5'b11111;

  // Normalization constant zero
  assign constzero = 5'b00000;

  assign normval = (switch_compare_1 == 1'b0 ? conststep :
              constzero);

  // Max value of state index
  assign idxmax = 4'b1111;

  always @(posedge clk or posedge reset)
    begin : MinimumTree_stage4_idx_1_process
      if (reset == 1'b1) begin
        MinimumTree_stage4_idx_reg <= 4'b0000;
      end
      else begin
        if (enb_1_2_0) begin
          MinimumTree_stage4_idx_reg <= MinimumTree_stage4_idx;
        end
      end
    end

  assign idx = idxmax - MinimumTree_stage4_idx_reg;

endmodule  // ACSRenorm

